// Route contract for this endpoint (read by wf.gateway.auth).
const route = {"method": "GET", "template": "/v1/admin/traces/:id", "require_user": true, "idempotent": false, "required_consents": [], "roles": ["admin"]};
const item = $input.first();
return [{ json: { ...item.json, t0: Date.now(), route }, binary: item.binary }];

// wf.api.admin_traces_get > "Build result"   GET /v1/admin/traces/:request_id (admins; spec 6.2, 8.3)
// Every execution recorded for the request id (API requests and jobs) with its agent steps, prompt versions,
// timings and tokens. A malformed or unknown id answers 404.
const gw = $('Gateway').first().json;
const t = ($input.first().json || {}).t;
if (!t || !Array.isArray(t.executions) || !t.executions.length) {
  return [{ json: { ok: false, gw, status: 404, error: { code: 'NOT_FOUND', message: 'No trace for this request id', details: [] } } }];
}
return [{ json: { ok: true, gw, status: 200, data: t } }];

// GET-by-id endpoints (jobs, evaluation runs) > "Database error"
// Error output of the database step: the client gets 503, the log gets the redacted text.
// Text of the error carried by an item on a node's error output.
// n8n puts either a string or an object {message, description, ...} in json.error.
function errorText(json) {
  const e = json && (json.error !== undefined ? json.error : json);
  if (e == null) return '';
  if (typeof e === 'string') return e;
  const parts = [e.message, e.description, e.cause && e.cause.message].filter((x) => typeof x === 'string' && x);
  return parts.length ? parts.join(' | ') : JSON.stringify(e);
}
// Postgres error details echo the offending value, e.g. Key (email)=(a@b.c).
// Values are removed before anything is logged.
function redactPg(msg) {
  return String(msg || '').replace(/\)=\([^)]*\)/g, ')=(redacted)');
}
if (typeof module !== 'undefined') module.exports = { errorText, redactPg };

const gw = $('Gateway').first().json;
const msg = errorText($input.first().json);
return [{ json: { ok: false, gw, status: 503, error: { code: 'UPSTREAM_UNAVAILABLE', message: 'A backend dependency is unavailable', details: [] }, log: { reason: 'database_error', detail: redactPg(msg).slice(0, 300) } } }];

// Shared by every API workflow > "Envelope"
// Input: either a handler result {ok:true, status, data, gw} or a rejection
// from the gateway or a handler {ok:false, status, error | replay+response}.
// Output: {status, response, finish} where finish is the app.api_finish payload.
const x = $input.first().json;
const gw = x.gw || x;                       // handlers carry the gateway item in x.gw
const t0 = gw.t0 || Date.now();
const latency = Date.now() - t0;
const requestId = gw.request_id || (gw.ctx && gw.ctx.request_id) || null;
let status, response;
if (x.replay) {
  status = x.status;
  response = x.response;                    // stored response, returned unchanged
} else if (x.ok) {
  status = x.status || 200;
  response = { request_id: requestId, data: x.data ?? {}, meta: { latency_ms: latency, ...(x.meta || {}) } };
} else {
  status = x.status || 500;
  const e = x.error || { code: 'INTERNAL', message: 'Internal error', details: [] };
  response = { request_id: requestId, error: { code: e.code, message: e.message, details: e.details || [] } };
}
const finish = {
  request_id: requestId,
  workflow: $workflow.name,
  n8n_execution_id: String($execution.id),
  user_id: (gw.ctx && gw.ctx.user_id) || '',
  channel: 'api',
  status_code: status,
  latency_ms: latency,
  error_code: response && response.error ? response.error.code : null,
  idempotency: gw.idempotency || null,
  idempotency_replay: !!x.replay,
  response_body: response,
  result_user_id: x.result_user_id || null,
  // agent steps of the request (spec 8.3), written to ai.agent_steps with the execution
  steps: Array.isArray(x.steps) ? x.steps : [],
  // reason and detail go to ai.executions.error only, never to the client
  error_detail: x.log ? [x.log.reason, x.log.detail].filter(Boolean).join(': ').slice(0, 500) : null,
};
const headers = { 'X-Request-Id': requestId || '', 'Cache-Control': 'no-store' };
if (status === 429) {
  const d = (response.error && response.error.details || []).find((y) => y.retry_after_s);
  if (d) headers['Retry-After'] = String(d.retry_after_s);
}
return [{ json: { status, response, finish, headers } }];
